$balSql="SELECT t.id,t.nombre,u.nombre unidad_nombre,l.nombre ubicacion_nombre,COALESCE(c.total,0) cargos,COALESCE(i.total,0) ingresos,COALESCE(i.total,0)-COALESCE(c.total,0) balance FROM inquilinos t LEFT JOIN unidades u ON u.id=t.unidad_id LEFT JOIN ubicaciones l ON l.id=u.ubicacion_id LEFT JOIN (SELECT inquilino_id,SUM(importe) total FROM cargos GROUP BY inquilino_id)c ON c.inquilino_id=t.id LEFT JOIN (SELECT inquilino_id,SUM(importe) total FROM ingresos GROUP BY inquilino_id)i ON i.inquilino_id=t.id WHERE t.estado='ACTIVO'";$balArgs=[];if($globalTenant){$balSql.=' AND t.id=?';$balArgs[]=$globalTenant;}if($globalLocation){$balSql.=' AND u.ubicacion_id=?';$balArgs[]=$globalLocation;}$balSql.=" ORDER BY balance ASC";$balStmt=$pdo->prepare($balSql);$balStmt->execute($balArgs);$balTenant=$balStmt->fetchAll();
