stado</label><select name="estado"><option value="ACTIVO" <?=val($edit??[],'estado','ACTIVO')==='ACTIVO'?'selected':''?>>Activo</option><option value="INACTIVO" <?=val($edit??[],'estado')==='INACTIVO'?'selected':''?>>Inactivo / se fue</option></select></div><div class="full"><label>Notas</label><textarea name="notas" rows="2"><?=val($edit??[],'notas')?></textarea></div><?php if(!$edit):?><div><label><input type="checkbox" name="crear_fianza" value="1" checked> ¿Añadir fianza ahora?</label></div><div><label>Importe fianza (€)</label><input type="number" min="0" step=".01" name="importe_fianza" value="450"></div><?php endif;?><div class="full actions"><button class="btn primary">Guardar inquilino</button><?php if($edit):?><a class="btn outline" href="index.php?page=inquilinos">Cancelar edición</a><?php endif;?></div></form></section></div><?php endif;?><section class="panel"><h3>Listado de inquilinos</h3><div class="table-wrap"><table><tr><th>Nombre / DNI</th><th>Ubicación / unidad</th><th>Contacto</th><th>Entrada / salida</th><th>Alquiler</th><th>Estado</th><th>Acciones</th></tr><?php foreach($tenants as $r):?><tr><td><?=e($r['nombre'])?><br><small><?=e($r['dni_nie'])?></small></td><td><?=e($r['ubicacion_nombre'])?><br><small><?=e($r['unidad_nombre']??$r['unidad'])?></small></td><td><?=e($r['telefono'])?><br><?=e($r['email'])?></td><td><?=e($r['fecha_entrada'])?><br><?=e($r['fecha_salida'])?></td><td><?=money($r['alquiler_mensual'])?></td><td><?=e($r['estado'])?></td><td class="actions"><a class="btn outline" href="index.php?page=inquilinos&edit=<?=$r['id']?>">Editar</a><a class="btn outline" href="pdf_inquilino.php?id=<?=$r['id']?>">PDF</a><?php if($user['rol']==='ADMIN'):?><form method="post" onsubmit="return confirm('¿Eliminar inquilino? Solo se puede si no tiene movimientos.')" ><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="tenant_delete"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="