<?php $listSql="SELECT x.*,t.nombre,u.nombre unidad_nombre,l.nombre ubicacion_nombre FROM $tbl x JOIN inquilinos t ON t.id=x.inquilino_id LEFT JOIN unidades u ON u.id=t.unidad_id LEFT JOIN ubicaciones l ON l.id=u.ubicacion_id WHERE 1=1";$listArgs=[];if($globalTenant){$listSql.=' AND x.inquilino_id=?';$listArgs[]=$globalTenant;}if($globalLocation){$listSql.=' AND u.ubicacion_id=?';$listArgs[]=$globalLocation;}$listSql.=" ORDER BY x.fecha DESC,x.id DESC";$listStmt=$pdo->prepare($listSql);$listStmt->execute($listArgs);$rows=$listStmt->fetchAll();foreach($rows as $r):?><tr><td><?=e($r['fecha'])?></td><td><?=e($r['nombre'])?></td><td><?=e($r['ubicacion_nombre'])?> / <?=e($r['unidad_nombre'])?></td><?php if($isC):?><td><?=e($r['concepto'])?></td><td><?=e($r['tipo'])?></td><td><?=e($r['pagado_por'])?></td><td><?=money($r['importe'])?></td><?php elseif($isI):?><td><?=e($r['concepto'])?></td><td><?=e($r['metodo'])?><?=($r['origen']!=='NORMAL'?' · '.$r['origen']:'')?></td><td><?=money($r['importe'])?></td><?php else:?><td><?=money($r['pagada'])?></td><td><?=money($r['a_devolver'])?></td><td><?=money($r['resto'])?></td><td><?=e($r['motivo_retencion'])?><br><small><?=e($r['detalle_retencion'])?></small></td><td><?=e($r['estado'])?></td><?php endif;?><td class="actions"><?php if(!$isI||$r['origen']==='NORMAL'):?><a class="btn outline" href="index.php?page=<?=$page?>&edit=<?=$r['id']?>">Editar</a><?php endif;?><?php if($isF && !(int)$r['liquidada']):?><form method="post" onsubmit="return confirm('¿Liquidar la fianza, compensar deuda y registrar daños?')"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="deposit_liquidate"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn" style="background:#f59e0b;color:#fff">Liquidar fianza</button></form><?php endif;?><?php if(!$isF||(int)$r['liquidada']===0):?><form method="post" onsubmit="return confirm('¿Borrar este registro?')"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="<?=$isC?'charge_delete':($isI?'income_delete':'deposit_delete')?>"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn danger">Borrar</button></form><?php endif;?></td></tr><?php endforeach;?></table></div></section>
