 nombre') as $r):?><tr><td><?=e($r['nombre'])?></td><td><?=e($r['email'])?></td><td><?=e($r['rol'])?></td><td><?=$r['activo']?'Sí':'No'?></td><td class="actions"><a class="btn outline" href="index.php?page=usuarios&edit=<?=$r['id']?>">Editar</a><?php if((int)$r['id']!==(int)$user['id']):?><form method="post" onsubmit="return confirm('¿Eliminar este usuario?')"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="user_delete"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn danger">Borrar</button></form><?php endif;?></td></tr><?php endforeach;?></table></div></section><?php endif;?>
